    cardShadowCollapsed: `0 2px ${px2(6)}px ${shadowInk(darkBg ? 0.4 : 0.08)}`,
    // Surface layers
    surfacePrimary: toHex(surface),
    surfaceSecondary: toHex(surfaceSecondary),
