    // Text
    textPrimary: toHex(textPrimary),
    textSecondary: toHex(textSecondary),
    textTertiary: toHex(textTertiary),
    textMuted: toHex(muted),
    // Accent
    accent: toHex(accent),
    accentLight: rgba(accent, G(0.12)),
    accentSoft: rgba(accent, G(darkBg ? 0.18 : 0.15)),
